export function resolveLanguage(params,storage){
 const normalize=value=>{const raw=String(value||'').toLowerCase();const code=raw.split('-')[0];if(LANGUAGES[code])return code;return Object.keys(LANGUAGES).find(k=>LANGUAGES[k].slice(0,2).some(name=>name.toLowerCase()===raw))||(raw==='gaelic'?'gd':null)};
 for(const value of [params.get('target'),params.get('ui'),storage?.getItem('lingototal_target_language'),storage?.getItem('lingototal_ui_language')]){const code=normalize(value);if(code)return code}return 'en';
}
export function setLanguage(code){const url=new URL(location.href);url.searchParams.set('ui',code);url.searchParams.set('target',code);location.assign(url.href)}

